ST.xhtml:p:
R_Trriger(CLK := bDustHomeEnable);

IF R_Trriger.Q THEN
  g_bDustHomeDone := FALSE;
  nHomeState := 1;
  bDustHomeEnable := FALSE;
END_IF;

CASE nHomeState OF
  0:
    nHomeState := 0;
  1:
    DustHome.Execute := TRUE;
    DustHome.Position := dDustHomePos;
    DustHome.bCalibrationCam := g_bDustHomeCal;
    DustHome.DISTANCE := dDustHomeOffset;
    IF bDustHomeMode = 0 THEN
      DustHome.HomingMode := 0;
    ELSIF bDustHomeMode = 1 THEN
      DustHome.HomingMode := 5;
     ELSIF bDustHomeMode = 3 THEN
      (*只是去掉回零标志位*)
      DustHome.HomingMode := 1;
    END_IF;
    IF DustHome.Done THEN
		DustHome.Execute := FALSE;
		g_bDustHomeDone := TRUE;
        nHomeState := 0;
    END_IF;
    IF g_bPlcPauseBuffer THEN
      nHomeState := 20;
    END_IF;
    IF DustHome.CommandAborted OR DustHome.Error THEN
      DustHome.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  20:
    DustHome.Execute := FALSE;
    DustAxis_Stop.Execute := TRUE;
    IF DustAxis_Stop.Done AND g_bPlcStartBuffer THEN
      DustAxis_Stop.Execute := FALSE;
      nHomeState := 1;
    END_IF;
    IF DustAxis_Stop.CommandAborted OR DustAxis_Stop.Error THEN
      DustAxis_Stop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
  21:
    DustHome.Execute := FALSE;
    DustAxis_Stop.Execute := TRUE;
    IF DustAxis_Stop.Done AND g_bPlcStartBuffer THEN
      DustAxis_Stop.Execute := FALSE;
      nHomeState := 1;
    END_IF;
    IF DustAxis_Stop.CommandAborted OR DustAxis_Stop.Error THEN
      DustAxis_Stop.Execute := FALSE;
      nHomeState := 0;
    END_IF;
END_CASE;

IF bChangeHomeMode THEN
  bChangeHomeMode := FALSE;
  nChangeHomeModeState := 1;
END_IF;

CASE nChangeHomeModeState OF
  0:
    nChangeHomeModeState := 0;
  1:
    DustHome.Execute := TRUE;
    IF bDustHomeMode = 0 THEN
      DustHome.HomingMode := 0;
    ELSIF bDustHomeMode = 1 THEN
      DustHome.HomingMode := 5;
    ELSIF bDustHomeMode = 2 THEN
      DustHome.HomingMode := 4;
    END_IF;
    DustHome.Position := 0.0;
    DustHome.DISTANCE := 0.0;
    IF DustHome.Done THEN
      DustHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
    IF DustHome.CommandAborted OR DustHome.Error THEN
      DustHome.Execute := FALSE;
      nChangeHomeModeState := 0;
    END_IF;
END_CASE;
(***界面上下发了去掉D轴回零标志***)
IF g_bCleanDHomed THEN
   DustHome.HomingMode := 1;
   DustHome.Execute := TRUE; 
   g_bDustHomeDone := FALSE; 
   IF DustHome.DONE OR DustHome.ERROR THEN 
    DustHome.Execute := FALSE; 
    g_bCleanDHomed := FALSE; 
   END_IF;
END_IF;

(*伺服断电恢复基准点*)
Rtring_DustRecover(CLK := g_bRecoverDustDatumMark);
IF Rtring_DustRecover.Q THEN
  g_bRecoverDustDatumMark := FALSE;
  nRecoverDustDatumMarkState := 1;
END_IF;
CASE nRecoverDustDatumMarkState OF
  1:
   DustHome.HomingMode := 4;
   DustHome.Position :=g_dDustDatumMark; (*恢复基准点坐标差值*)
   DustHome.Execute := TRUE;  
   IF  DustHome.DONE OR DustHome.ERROR THEN 
      g_bDustHomeDone := TRUE;
    DustHome.Execute := FALSE; 
    nRecoverDustDatumMarkState := 0; 
   END_IF;
END_CASE;

(*防甩轴3==抽尘轴2*)
Rtring3(CLK := g_biAntiRejection3HomeEnable OR bAntiRejection3HomeEnable OR g_bAntiRejection3HomeEnable);

IF Rtring3.Q THEN
  nHomingState3 :=1;
  g_boAntiRejection3HomeDone := FALSE;
  g_bAntiRejection3HomeDone :=FALSE;
END_IF;

CASE nHomingState3 OF 
  0:
  nHomingState3 := 0;
  1:
  g_AntiRejection3Home.Execute := TRUE;
  g_AntiRejection3Home.Position := dHomePosition3;
  g_AntiRejection3Home.bCalibrationCam := g_boAntiRejection3HomeSignal;
  g_AntiRejection3Home.DISTANCE := dHomeOffset3;
  IF nHomingMode3 =0 THEN
    g_AntiRejection3Home.HomingMode := 0;
  ELSIF nHomingMode3 = 1 THEN
    g_AntiRejection3Home.HomingMode := 5;
  ELSIF nHomingMode3 = 3 THEN
    (*只是去掉回零标志位*)
    g_AntiRejection3Home.HomingMode := 1;  
  END_IF;
  IF g_AntiRejection3Home.Done THEN
    g_AntiRejection3Home.Execute := FALSE;
    g_boAntiRejection3HomeDone := TRUE;
    g_bAntiRejection3HomeDone := TRUE;
    nHomingState3 := 0;
  END_IF;
  IF g_bPlcPauseBuffer THEN
    nHomingState3 := 10;
  END_IF;
  IF g_AntiRejection3Home.CommandAborted OR g_AntiRejection3Home.error THEN
    nHomingState3 := 0;
    g_AntiRejection3Home.Execute := FALSE;
    g_boAntiRejection3HomeDone := FALSE;
    g_bAntiRejection3HomeDone := FALSE;
  END_IF;
  10:
  g_AntiRejection3Home.Execute := FALSE;
  g_AntiRejection3Stop.Execute := TRUE;
  IF g_AntiRejection3Stop.Done AND g_bPlcStartBuffer THEN
    g_AntiRejection3Stop.Execute := FALSE;
    nHomingState3 := 1;
  END_IF;
  IF g_AntiRejection3Stop.CommandAborted OR g_AntiRejection3Stop.error THEN
    g_AntiRejection3Stop.Execute := FALSE;
    nHomingState3 :=0;
  END_IF;
END_CASE;



IF bChangeHomeMode1 THEN
  bChangeHomeMode1 := FALSE;
  nChangeHomeModeState1 := 1;
END_IF;

CASE nChangeHomeModeState1 OF
  0:
    nChangeHomeModeState1 := 0;
  1:
    g_AntiRejection3Home.Execute := TRUE;
    IF nHomingMode3 = 0 THEN
      g_AntiRejection3Home.HomingMode := 0;
    ELSIF nHomingMode3 = 1 THEN
      g_AntiRejection3Home.HomingMode := 5;
    ELSIF nHomingMode3 = 2 THEN
      g_AntiRejection3Home.HomingMode := 4;
    END_IF;
    IF g_AntiRejection3Home.Done THEN
      g_AntiRejection3Home.Execute := FALSE;
      nChangeHomeModeState1 := 0;
    END_IF;
    IF g_AntiRejection3Home.CommandAborted OR g_AntiRejection3Home.Error THEN
      g_AntiRejection3Home.Execute := FALSE;
      nChangeHomeModeState1 := 0;
    END_IF;
END_CASE;
(***界面上下发了去掉D轴回零标志***)
IF bCleanD2Homed THEN
   g_AntiRejection3Home.HomingMode := 1;
   g_AntiRejection3Home.Execute := TRUE; 
   g_bAntiRejection3HomeDone := FALSE; 
   IF g_AntiRejection3Home.DONE OR g_AntiRejection3Home.ERROR THEN 
    g_AntiRejection3Home.Execute := FALSE; 
    bCleanD2Homed := FALSE; 
   END_IF;
END_IF;

(*伺服断电恢复基准点*)
Rtring_Dust2Recover(CLK := g_bRecoverDust2DatumMark);
IF Rtring_Dust2Recover.Q THEN
  g_bRecoverDust2DatumMark := FALSE;
  nRecoverDust2DatumMarkState := 1;
END_IF;
CASE nRecoverDust2DatumMarkState OF
  1:
   g_AntiRejection3Home.HomingMode := 4;
   g_AntiRejection3Home.Position :=g_dDust2DatumMark; (*恢复基准点坐标差值*)
   g_AntiRejection3Home.Execute := TRUE;  
   IF  g_AntiRejection3Home.DONE OR g_AntiRejection3Home.ERROR THEN 
    g_boAntiRejection3HomeDone := TRUE;
    g_bAntiRejection3HomeDone := TRUE;
    g_AntiRejection3Home.Execute := FALSE; 
    nRecoverDust2DatumMarkState := 0; 
   END_IF;
END_CASE;

IF g_bPlcResetBuffer THEN
  DustHome.Execute := FALSE;
  DustAbsolute.Execute := FALSE;
  DustAxis_Stop.Execute := FALSE;
  nHomeState := 0;
  nChangeHomeModeState := 0;
  g_bDustHomeDone := TRUE;
  g_AntiRejection3Home.Execute := FALSE;
  nHomingState3 :=0;
  g_AntiRejection3Rel.Execute := FALSE;
  g_AntiRejection3Stop.Execute := FALSE;
  g_bAntiRejection3HomeDone := TRUE;
  g_bRecoverDust2DatumMark := FALSE;
  g_bRecoverDustDatumMark := FALSE;
END_IF;
g_nDHomeMode := bDustHomeMode;
g_nD2HomeMode := nHomingMode3;
